-- JudgeX foundation. Apply to a new development Supabase project first.
create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 120),created_at timestamptz not null default now());
create table public.organization_memberships(organization_id uuid references public.organizations on delete cascade,user_id uuid references auth.users on delete cascade,role text not null check(role in ('owner','organizer')),primary key(organization_id,user_id));
create table public.events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,name text not null,description text not null default '',timezone text not null default 'Asia/Kolkata',starts_at timestamptz,registration_ends_at timestamptz,submission_ends_at timestamptz,appeals_ends_at timestamptz,location text not null default '',join_code uuid not null unique default gen_random_uuid(),status text not null default 'draft' check(status in ('draft','published','evaluating','released','archived')),team_limit integer not null default 50 check(team_limit between 1 and 1000),team_size integer not null default 4 check(team_size between 1 and 20),recording_policy text not null default 'Recording is optional. Uploaded presentation evidence may be used instead.',recording_policy_version text not null default '1',retention_days integer not null default 30 check(retention_days between 1 and 365),created_at timestamptz not null default now(),released_at timestamptz);
create table public.event_memberships(event_id uuid references public.events on delete cascade,user_id uuid references auth.users on delete cascade,role text not null check(role in ('organizer','participant')),primary key(event_id,user_id));
create table public.problem_statements(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,version integer not null default 1,title text not null,body text not null,deliverables text not null default '',created_at timestamptz not null default now());
create table public.teams(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,name text not null,captain_id uuid not null references auth.users,created_at timestamptz not null default now(),unique(event_id,name),unique(id,event_id));
create table public.team_memberships(team_id uuid not null,event_id uuid not null,user_id uuid not null references auth.users,accepted_at timestamptz not null default now(),foreign key(team_id,event_id) references public.teams(id,event_id),primary key(team_id,user_id),unique(event_id,user_id));
create table public.invitations(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams,email text not null,token_hash text not null unique,status text not null default 'pending' check(status in ('pending','accepted','declined','revoked')),expires_at timestamptz not null default now()+interval '7 days',created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),team_id uuid not null unique references public.teams,title text not null default '',abstract text not null default '',architecture text not null default '',tech_stack text[] not null default '{}',repository_url text not null default '',demo_url text not null default '',updated_at timestamptz not null default now());
create table public.rubric_versions(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,version integer not null default 1,criteria jsonb not null check(jsonb_typeof(criteria)='array'),frozen_at timestamptz,unique(event_id,version));
create table public.submission_versions(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,version integer not null,content jsonb not null,checksum text not null,rubric_id uuid not null references public.rubric_versions,locked_at timestamptz not null default now(),locked_by uuid not null references auth.users,unique(project_id,version));
create table public.artifacts(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams,submission_id uuid references public.submission_versions,object_key text not null unique,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 104857600),checksum text,kind text not null check(kind in ('slides','recording','image','document')),scan_state text not null default 'pending' check(scan_state in ('pending','clean','rejected')),created_by uuid not null references auth.users,created_at timestamptz not null default now());
create table public.presentation_slots(id uuid primary key default gen_random_uuid(),team_id uuid not null unique references public.teams,starts_at timestamptz not null,duration_minutes integer not null default 15 check(duration_minutes between 1 and 120),room text not null default 'Room A',checked_in_at timestamptz,status text not null default 'scheduled' check(status in ('scheduled','ready','presenting','complete','missed')));
create table public.consents(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams,user_id uuid not null references auth.users,policy_version text not null,purpose text not null,accepted boolean not null,created_at timestamptz not null default now());
create table public.evidence_items(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submission_versions,artifact_id uuid references public.artifacts,source text not null,content text not null,page integer,timestamp_seconds numeric,created_at timestamptz not null default now());
create table public.assessment_runs(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submission_versions,provider text not null,model text not null,prompt_version text not null,rubric_id uuid not null references public.rubric_versions,status text not null default 'queued' check(status in ('queued','running','complete','failed','manual_review')),output jsonb,error text,created_at timestamptz not null default now());
create table public.approved_scorecards(id uuid primary key default gen_random_uuid(),submission_id uuid not null unique references public.submission_versions,scores jsonb not null,weighted_total numeric not null check(weighted_total between 0 and 100),feedback text not null check(length(trim(feedback))>0),approved_by uuid not null references auth.users,approved_at timestamptz not null default now(),decision_version integer not null default 1);
create table public.score_changes(id uuid primary key default gen_random_uuid(),scorecard_id uuid not null references public.approved_scorecards,previous_scores jsonb,new_scores jsonb not null,reason text not null,actor_id uuid not null references auth.users,created_at timestamptz not null default now());
create table public.appeals(id uuid primary key default gen_random_uuid(),scorecard_id uuid not null references public.approved_scorecards,user_id uuid not null references auth.users,criterion_id text,reason text not null,status text not null default 'open' check(status in ('open','reviewing','resolved','declined')),resolution text,created_at timestamptz not null default now());
create table public.jobs(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,team_id uuid references public.teams,kind text not null check(kind in ('extract','assess','email','report','repository')),payload jsonb not null default '{}',idempotency_key text not null unique,status text not null default 'queued' check(status in ('queued','running','complete','retry','dead')),attempts integer not null default 0,available_at timestamptz not null default now(),lease_until timestamptz,last_error text,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,user_id uuid not null references auth.users,kind text not null,logical_key text not null unique,status text not null default 'queued' check(status in ('queued','sent','delivered','bounced','failed')),provider_id text,last_error text,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),event_id uuid references public.events,actor_id uuid references auth.users,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.usage_records(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events,metric text not null,quantity numeric not null check(quantity>=0),created_at timestamptz not null default now());

create function public.is_event_organizer(e uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from event_memberships where event_id=e and user_id=auth.uid() and role='organizer') $$;
create function public.is_event_member(e uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from event_memberships where event_id=e and user_id=auth.uid()) $$;
create function public.is_team_member(t uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from team_memberships where team_id=t and user_id=auth.uid()) $$;
create function public.can_read_team(t uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from teams where id=t and (is_event_organizer(event_id) or is_team_member(id))) $$;
create function public.can_read_submission(s uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from submission_versions v join projects p on p.id=v.project_id where v.id=s and can_read_team(p.team_id)) $$;
create function public.can_read_scorecard(s uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from submission_versions v join projects p on p.id=v.project_id join teams t on t.id=p.team_id join events e on e.id=t.event_id where v.id=s and (is_event_organizer(e.id) or (e.status='released' and is_team_member(t.id)))) $$;

-- Default-deny every table. Writes are granted only through bounded RPCs below.
do $$ declare t text; begin foreach t in array array['organizations','organization_memberships','events','event_memberships','problem_statements','teams','team_memberships','invitations','projects','rubric_versions','submission_versions','artifacts','presentation_slots','consents','evidence_items','assessment_runs','approved_scorecards','score_changes','appeals','jobs','notifications','audit_logs','usage_records'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create policy org_read on organizations for select to authenticated using(exists(select 1 from organization_memberships m where m.organization_id=id and m.user_id=auth.uid()));
create policy org_member_read on organization_memberships for select to authenticated using(user_id=auth.uid());
create policy event_read on events for select to authenticated using(is_event_member(id));
create policy event_member_read on event_memberships for select to authenticated using(user_id=auth.uid() or is_event_organizer(event_id));
create policy problem_read on problem_statements for select to authenticated using(is_event_member(event_id));
create policy team_read on teams for select to authenticated using(can_read_team(id));
create policy team_member_read on team_memberships for select to authenticated using(can_read_team(team_id));
create policy invitation_read on invitations for select to authenticated using(exists(select 1 from teams t where t.id=team_id and is_event_organizer(t.event_id)) or lower(email)=lower(auth.jwt()->>'email'));
create policy project_read on projects for select to authenticated using(can_read_team(team_id));
create policy rubric_read on rubric_versions for select to authenticated using(is_event_member(event_id));
create policy submission_read on submission_versions for select to authenticated using(can_read_submission(id));
create policy artifact_read on artifacts for select to authenticated using(can_read_team(team_id));
create policy slot_read on presentation_slots for select to authenticated using(can_read_team(team_id));
create policy consent_read on consents for select to authenticated using(user_id=auth.uid() or exists(select 1 from teams t where t.id=team_id and is_event_organizer(t.event_id)));
create policy evidence_read on evidence_items for select to authenticated using(can_read_submission(submission_id));
create policy assessment_read on assessment_runs for select to authenticated using(exists(select 1 from submission_versions v join projects p on p.id=v.project_id join teams t on t.id=p.team_id where v.id=submission_id and is_event_organizer(t.event_id)));
create policy scorecard_read on approved_scorecards for select to authenticated using(can_read_scorecard(submission_id));
create policy score_change_read on score_changes for select to authenticated using(exists(select 1 from approved_scorecards s join submission_versions v on v.id=s.submission_id join projects p on p.id=v.project_id join teams t on t.id=p.team_id where s.id=scorecard_id and is_event_organizer(t.event_id)));
create policy appeal_read on appeals for select to authenticated using(user_id=auth.uid() or exists(select 1 from approved_scorecards s join submission_versions v on v.id=s.submission_id join projects p on p.id=v.project_id join teams t on t.id=p.team_id where s.id=scorecard_id and is_event_organizer(t.event_id)));
create policy job_read on jobs for select to authenticated using(is_event_organizer(event_id));
create policy notification_read on notifications for select to authenticated using(user_id=auth.uid() or is_event_organizer(event_id));
create policy audit_read on audit_logs for select to authenticated using(is_event_organizer(event_id));
create policy usage_read on usage_records for select to authenticated using(is_event_organizer(event_id));
create index jobs_ready on jobs(status,available_at);
create index teams_event on teams(event_id);
create index evidence_submission on evidence_items(submission_id);
create index audit_event on audit_logs(event_id,created_at desc);
create index submission_project on submission_versions(project_id,version desc);
